from .cupom import aplicar_cupom
from .impostos import imposto


def total_pedido(subtotal, percentual_cupom=0):
    base = aplicar_cupom(subtotal, percentual_cupom) if percentual_cupom else subtotal
    return round(base + imposto(base), 2)

